package sem

import "testing"

func TestTrail135NestedClassReceiverResolvesToDefinition(t *testing.T) {
	repo := t.TempDir()
	writeFile(t, repo, "nested.hpp", `class Outer {
public:
    class Inner {
    public:
        int Add(int amount) const;
    };
};
`)
	writeFile(t, repo, "nested.cpp", `#include "nested.hpp"
int Outer::Inner::Add(int amount) const { return amount + 1; }
`)
	writeFile(t, repo, "main.cpp", `#include "nested.hpp"
int run() {
    Outer::Inner value;
    return value.Add(3);
}
`)
	snapshot, err := BuildProviderSnapshot(t.Context(), repo, "test-version")
	if err != nil {
		t.Fatal(err)
	}
	byID := map[string]SymbolRecord{}
	for _, symbol := range snapshot.Symbols {
		byID[symbol.ID] = symbol
	}
	for _, relation := range snapshot.Relations {
		if relation.Type == "CALLS" && byID[relation.FromID].Name == "run" && byID[relation.ToID].Name == "Add" {
			if got := byID[relation.ToID].FilePath; got != "nested.cpp" {
				t.Fatalf("run resolves Add to %s, want nested.cpp definition", got)
			}
			return
		}
	}
	t.Fatal("run has no CALLS edge to Add")
}

