ns::Thing Holder::build() { return ns::Thing{}; }

int plain(int a) { return a; }

template <typename T>
T identity(T x) { return x; }
`
	kinds := parseCPlusPlus(t, src)
	for _, name := range []string{"makeThing", "toText", "ptrFn", "refFn", "build", "plain", "identity"} {
